// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let types = 6;
let type = 1 / types;
let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

var c1, c2, c3, c4, c5, c6;
var cc;

function mousePressed() {
	redraw();
}

function setup() {
  createCanvas(w, h);
	pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
  cc = color(0,0,0,100);
}

function drawTileF(px, py, d, alpha) {
  push();
  translate(px, py);

  var cd = color(cc);
  cd.setAlpha(alpha);

  stroke(cd);
  noFill();

	if(random() < 0.5) {
	  arc(d, 0, d, d, PI/2, PI);
	} else {
	  arc(0, d, d, d, -PI/2, 0);
	}

	if(random() < 0.5) {
	  arc(0, 0, d, d, 0, PI/2);
	} else {
	  arc(d, d, d, d, -PI, -PI/2);
	}
  pop();
}

function drawTileE(px, py, d, alpha) {
  push();
  translate(px+d/2, py+d/2);

  rotate(int(random(0, 4)) * PI/2);
  noFill();
  var cd = color(cc);
  cd.setAlpha(alpha);

  stroke(cd);
  line(0, 0, d/2, 0);
  line(0, 0, 0, d/2);
  arc(-d/2, -d/2, d, d, 0, PI/2);

  noStroke();
  circle(0, 0, d/3);

  pop();
}

function drawTileD(px, py, d, alpha) {
  push();
  translate(px, py);

  noFill();
  var cd = color(cc);
  cd.setAlpha(alpha);

  stroke(cd);  line(0, d/2, d, d/2);
  line(d/2, 0, d/2, d);
  fill(0,0,0, alpha);
  stroke(c3, alpha);
  fill(220);
  circle(-d/2, -d/2, d/3);
  pop();
}

function drawTileC(px, py, d, alpha) {
  push();
  translate(px, py);

  var cd = color(cc);
  cd.setAlpha(alpha);

  stroke(cd);
  noFill();
  arc(0, 0, d, d, 0, PI/2);
  arc(d, d, d, d, -PI, -PI/2);

  rectMode(CENTER);
  var m = random();
  noStroke();
  if(m < 0.2) {
	  fill(c4, alpha);
    rect(d*3/4, d/4, d/3);
  } else if (m < 0.4) {
	  fill(c6, alpha);
    rect(d/4, d*3/4, d/3);
  }
  pop();
}

function drawTileB(px, py, d, alpha) {
  push();
  translate(px, py);

  var cd = color(cc);
  cd.setAlpha(alpha);

  stroke(cd);
  noFill();
  arc(d, 0, d, d, PI/2, PI);
  arc(0, d, d, d, -PI/2, 0);
  pop();
}

function drawTileA(px, py, d, alpha) {
  push();
  translate(px, py);

  var m = random();
  var cc1 = color(c1);
  cc1.setAlpha(alpha);
  var cc2 = color(c2);
  cc2.setAlpha(alpha);
  var cc3 = color(c3);
  cc3.setAlpha(alpha);

  if(m < 0.94) {
    noFill();
    stroke(cc1); 
    rect(0,0, d, d);

		m = random();
		if(m < 0.2) {
			if(random() < 0.4) {
				fill(cc2);    
			} else {
				fill(cc3);
			}
			noStroke();
			circle(-d/2, d/2, d/3);    
		} else if(m < 0.25) {
			noFill();
			stroke(cc1);
			line(0, 0, d, d);
			line(d, 0, 0, d);
		} else if(m < 0.3) {
			noFill();
			stroke(cc1);
			line(d/4, 0, d/4, d);
			line(d/2, 0, d/2, d);
			line(d*3/4, 0, d*3/4, d);
		} else if(m < 0.35) {
			noFill();
			stroke(cc1);
			line(0, d/4, d, d/4);
			line(0, d/2, d, d/2);
			line(0, d*3/4, d, d*3/4);
		}

	} else {
    stroke(c5, alpha);
    fill(c5, alpha);
		rect(0,0, d, d);
  }

  pop();
}

function drawTile(px, py, d, w, alpha) {
  var m = random();

  strokeWeight(w);

  if (m < type) {
    drawTileA(px, py, d, alpha);
  } else if (m < type*2) {
    drawTileB(px, py, d, alpha);
  } else if (m < type*3) {
    drawTileC(px, py, d, alpha);
  } else if (m < type*4) {
    drawTileD(px, py, d, alpha);
  } else if (m < type*5) {
    drawTileE(px, py, d, alpha);
  } else {
    drawTileF(px, py, d, alpha);
  }

}

function draw() {
  background(220);


  shuffle(pal, true);
  c1 = color( pal[0] );
  c2 = color( pal[1] );
  c3 = color( pal[2] );
  c4 = color( pal[3] );
  c5 = color( pal[4] );
  c6 = color( pal[5] );

  var px, py;


  // 2*42
  // 3*28 o
  // 4*21
  // 6*14 o
  // 7*12
  // 12*7 o
  // 14*6

	var k;

	if(random() < 0.5) {
		k = s*42;
		for(let i = 0; i < 2; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 2; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 9, 30);
			}
		}
	}

	if(random() < 0.5) {
		k = s*28;
		for(let i = 0; i < 3; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 3; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 3, 100);
			}
		}
	}

	if(random() < 0.5) {
		k = s*14;
		for(let i = 0; i < 6; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 6; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 6, 50);
			}    
		}	
	}

	if(random() < 0.5) {  
		k = s*7;
		for(let i = 0; i < 12; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 12; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 3, 70);
			}    
		}
	}

	if(random() < 0.5) {  
		k = s*3;
		for(let i = 0; i < 28; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 28; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 2, 80);
			}    
		}
	}

	if(random() < 0.5) {  
		k = s*2;
		for(let i = 0; i < 42; i++) {
			py = s*4 + i * k;
			for(let j = 0; j < 42; j++) {
				px = s*4 + j * k;
				drawTile(px, py, k, 1, 100);
			}    
		}
	}

  drawGrids();
  drawFrame();
}

// ------------------------------ //
// ------------------------------ //
// ------------------------------ //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  }
}

function drawFrame() {
  rectMode(CENTER);

  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor() {
  var l = pal.length;
  var cc = random();
  // shuffle(pal, true);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

